alter table public.family_education_invitations add column if not exists event_weekday text not null default ''; alter table public.family_education_invitations add column if not exists approval_status text not null default 'pending'; alter table public.family_education_invitations add column if not exists manager_note text not null default ''; alter table public.family_education_invitations add column if not exists manager_reviewed_by uuid references auth.users(id) on delete set null; alter table public.family_education_invitations add column if not exists manager_reviewed_at timestamptz; update public.family_education_invitations set approval_status='approved' where approval_status='pending'; alter table public.family_education_invitations add constraint family_education_invitations_approval_status_check check (approval_status in ('pending','approved','rejected')); create index if not exists family_education_invitations_approval_idx on public.family_education_invitations (tenant_school_id, approval_status, invited_at desc);